#include "upload_scheduler.h"

#include "config.h"
#include "ntp_time.h"
#include "s3_uploader.h"
#include "sd_storage.h"

namespace upload_scheduler {

namespace {
bool g_uploaded_today = false;
bool g_boot_catchup_done = false;
} // namespace

void begin() {
  g_uploaded_today = false;
  g_boot_catchup_done = false;
}

namespace {

void run_upload_pass() {
  if (!sd_storage::lock()) {
    return;
  }

  for (const auto &path : sd_storage::list_recordings()) {
    if (s3_uploader::upload_file(path)) {
      sd_storage::remove_file(path);
    }
    // On failure, leave the file in place — retried on the next pass.
  }

  sd_storage::unlock();
}

} // namespace

void tick() {
  if (!ntp_time::is_synced()) {
    return;
  }

  if (!g_boot_catchup_done) {
    g_boot_catchup_done = true;
    run_upload_pass(); // no-op if nothing to upload
  }

  tm t = ntp_time::local_now();
  if (t.tm_hour == kUploadHour) {
    if (!g_uploaded_today) {
      run_upload_pass();
      g_uploaded_today = true;
    }
  } else {
    g_uploaded_today = false; // re-arm once we leave the upload hour
  }
}

} // namespace upload_scheduler
#include "mqtt_client.h"

#include <Arduino.h>
#include <PubSubClient.h>
#include <WiFi.h>

#include <cstring>

#include "audio_capture.h"
#include "config.h"
#include "wifi_manager.h"

namespace mqtt_client {

namespace {

WiFiClient g_wifi_client;
PubSubClient g_client(g_wifi_client);
uint32_t g_last_reconnect_attempt_ms = 0;
constexpr uint32_t kReconnectIntervalMs = 5000;

void on_message(char *topic, uint8_t *payload, unsigned int length) {
  (void)topic;
  (void)payload;
  (void)length;
  // Any message on the trigger topic fires a recording — matches
  // data_collection/data_collector.py's default (no mqtt_trigger_value set).
  audio_capture::request_recording();
}

bool connect() {
  const char *client_id_suffix = DEVICE_ID;
  String client_id = String("esp32-sense-") + client_id_suffix;

  bool ok;
  if (strlen(MQTT_USERNAME) > 0) {
    ok = g_client.connect(client_id.c_str(), MQTT_USERNAME, MQTT_PASSWORD);
  } else {
    ok = g_client.connect(client_id.c_str());
  }

  if (ok) {
    g_client.subscribe(MQTT_TRIGGER_TOPIC);
  }
  return ok;
}

} // namespace

void begin() {
  g_client.setServer(MQTT_HOST, MQTT_PORT);
  g_client.setCallback(on_message);
}

void loop_tick() {
  if (!wifi_manager::is_connected()) {
    return;
  }

  if (!g_client.connected()) {
    if (millis() - g_last_reconnect_attempt_ms >= kReconnectIntervalMs) {
      g_last_reconnect_attempt_ms = millis();
      connect();
    }
    return;
  }

  g_client.loop();
}

bool is_connected() { return g_client.connected(); }

} // namespace mqtt_client
#include "sd_storage.h"

#include <SPI.h>

#include "config.h"

namespace sd_storage {

namespace {
SemaphoreHandle_t g_mutex = nullptr;
}

bool begin() {
  g_mutex = xSemaphoreCreateMutex();
  if (g_mutex == nullptr) {
    return false;
  }

  if (!SD.begin(kSdCsPin)) {
    return false;
  }

  if (!SD.exists(kRecordingsDir)) {
    SD.mkdir(kRecordingsDir);
  }

  return true;
}

bool lock(uint32_t timeout_ms) {
  return xSemaphoreTake(g_mutex, timeout_ms == portMAX_DELAY
                                     ? portMAX_DELAY
                                     : pdMS_TO_TICKS(timeout_ms)) == pdTRUE;
}

void unlock() { xSemaphoreGive(g_mutex); }

std::vector<std::string> list_recordings() {
  std::vector<std::string> out;

  File dir = SD.open(kRecordingsDir);
  if (!dir || !dir.isDirectory()) {
    return out;
  }

  File entry = dir.openNextFile();
  while (entry) {
    if (!entry.isDirectory()) {
      std::string name = entry.name();
      const bool is_wav = name.size() > 4 &&
                           name.compare(name.size() - 4, 4, ".wav") == 0;
      if (is_wav) {
        // Depending on the core version, File::name() from a directory
        // iterator may return a bare filename or an already-absolute path —
        // handle both rather than assume one.
        std::string path = (!name.empty() && name[0] == '/')
                                ? name
                                : std::string(kRecordingsDir) + "/" + name;
        out.push_back(path);
      }
    }
    entry = dir.openNextFile();
  }

  return out;
}

bool remove_file(const std::string &path) { return SD.remove(path.c_str()); }

size_t file_size(const std::string &path) {
  File f = SD.open(path.c_str(), FILE_READ);
  if (!f) {
    return 0;
  }
  size_t size = f.size();
  f.close();
  return size;
}

std::string temp_path_for(const std::string &final_path) {
  return final_path + kTempSuffix;
}

bool commit_temp_file(const std::string &final_path) {
  return SD.rename(temp_path_for(final_path).c_str(), final_path.c_str());
}

} // namespace sd_storage

